import sys

def main():
    main_list = []
    nested_list = []
    input_data = sys.stdin.read().split()
    size = int(input_data[0])
    input_string = input_data[1]
    extended_input = input_string + "^"
    total_size = size + 1
    buffer = list(extended_input.ljust(256, '^'))  # ensure buffer length

    inside_parentheses = 0
    current_segment = ""
    for i in range(total_size):
        if buffer[i] == '(':
            inside_parentheses = 1
            buffer[i] = '^'
            continue
        elif buffer[i] == ')':
            inside_parentheses = 0
            nested_list.append(current_segment)
            buffer[i] = '^'
            current_segment = ""
        if inside_parentheses == 1:
            current_segment += buffer[i]
            buffer[i] = '^'
    current_segment = ""
    for i in range(total_size):
        if buffer[i] == '^':
            if not current_segment:
                continue
            main_list.append(current_segment)
            current_segment = ""
        else:
            current_segment += buffer[i]
    max_letter_count = 0
    for segment in main_list:
        temp = segment + "_"
        letter_count = 0
        for ch in temp:
            if ch.isalpha():
                letter_count += 1
            elif ch == '_':
                max_letter_count = max(max_letter_count, letter_count)
                letter_count = 0
    word_counter = 0
    for segment in nested_list:
        temp = segment + "_"
        word_builder = ""
        for ch in temp:
            if ch.isalpha():
                word_builder += ch
            elif ch == '_' and word_builder:
                word_builder = ""
                word_counter += 1
    print(f"{max_letter_count} {word_counter}")

if __name__ == "__main__":
    main()

